           (s.net_amount IS NOT NULL
            AND NULLIF(BTRIM(s.item_code), '') IS NULL AND s.product_id IS NULL
            AND NULLIF(BTRIM(s.uom), '') IS NULL AND s.quantity IS NULL AND s.unit_price IS NULL
